head.b:skin:
/* 
-----------------------------------------------
Blogger Theme Style
Name:          Cinhub4u
Version:       0.1 Pro
Published:   4-July-2023
Author:         BlogifyPro
Author Url:   https://blogify-pro.blogspot.com
----------------------------------------------- */

/* Variable Definitions
-----------------------
<Variable name="keycolor" description="Main Color" type="color" default="$(main.color)" value="#d52c1f"/>
<Variable name="main.color" description="Theme Color" type="color" default="#448AFF" value="#ff493b"/>
<Variable name="followByEmail" description="Follow By Email Text" type="string" default="Get all latest content delivered straight to your inbox." value="Get all latest content delivered straight to your inbox."/>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body Background Color" type="color" default="#f7f7f7"  value="#f5f5f5"/>
  <Variable name="body.background" description="Background" type="background" color="$(body.background.color)" default="$(color) url() repeat fixed top left" value="$(color) url() repeat fixed top left"/>
  <Variable name="body.text.color" description="Text Color" type="color" default="#656565"  value="#595959"/>
  <Variable name="body.link.color" description="Link Color" type="color" default="$(main.color)"  value="#448AFF"/>
</Group>

<!-- Extra Variables -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="13px Ruda, sans-serif"  value="13px Ruda, sans-serif"/>
<Variable name="posts.background.color" description="Post background color" hideEditor="true" type="color" default="#ffffff"  value="#ffffff"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="13px Ruda, sans-serif"  value="13px Ruda, sans-serif"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="#000000"  value="#000000"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="#656565"  value="#595959"/>
<Variable name="posts.link.color" description="Post link color" type="color" default="$(body.link.color)"  value="#448AFF"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#448AFF"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)"  value="#448AFF"/>

