.cinhub-home-description h2{letter-spacing:.15px;font-size:clamp(20px,3vw,27px)!important}
.cinhub-home-description p{color:#bdbdbd!important;max-width:900px}
#top-popular-slider .widget-title{background:transparent!important;border-left:3px solid var(--cinhub-accent)!important;border-bottom:1px solid #252525;border-radius:0!important;padding:10px 12px!important;letter-spacing:.2px}
#top-popular-slider .widget-content{max-width:360px!important;height:390px!important;overflow:visible!important}
#top-popular-slider .post{border:1px solid #383838!important;border-radius:10px!important;background:#111!important;box-shadow:0 12px 32px rgba(0,0,0,.45);will-change:transform,opacity,filter}
#top-popular-slider .post.cinhub-active{border-color:#555!important;box-shadow:0 12px 36px rgba(0,0,0,.55)!important;animation:none!important}
#top-popular-slider .post.cinhub-next{transform:translateX(28%) scale(.82)!important}
#top-popular-slider .post.cinhub-prev{transform:translateX(-128%) scale(.78)!important}
#top-popular-slider .post-info{background:#111!important}
#top-popular-slider .post-title a:hover{color:#eee!important}
.cinhub-slider-controls{position:absolute;left:0;right:0;top:43%;z-index:8;display:flex;justify-content:space-between;padding:0 2px;pointer-events:none}
.cinhub-slider-arrow{pointer-events:auto;display:flex;align-items:center;justify-content:center;width:34px;height:34px;border:1px solid #414141;border-radius:50%;background:rgba(12,12,12,.88);color:#fff;font-size:25px;line-height:1;cursor:pointer;box-shadow:0 3px 12px #0008;transition:background .2s ease,border-color .2s ease}
.cinhub-slider-arrow:hover,.cinhub-slider-arrow:focus-visible{background:#242424;border-color:#888;outline:none}
.cinhub-slider-dots{position:absolute;left:0;right:0;bottom:-22px;display:flex;justify-content:center;gap:6px;z-index:9}
.cinhub-slider-dot{width:6px;height:6px;min-width:6px;padding:0;border:0;border-radius:99px;background:#555;cursor:pointer;transition:width .2s ease,background .2s ease}
.cinhub-slider-dot.is-active{width:20px;background:#eee}
.index-post-inside-wrap,.featured-item-inner{border:1px solid #303030!important;border-radius:9px!important;box-shadow:0 5px 18px rgba(0,0,0,.28)!important;animation:none!important}
.index-post .post-info{background:#111!important;min-height:90px!important}
.index-post .post-info>h2{font-weight:600!important}
.cinhub-language-nav{background:#050505!important;border-bottom:1px solid #222!important;gap:10px!important}
.cinhub-language-nav a{background:#111!important;border:1px solid #333!important;border-radius:999px!important;box-shadow:none!important;animation:none!important}
.cinhub-language-nav a:hover{background:#222!important;border-color:#777!important;transform:translateY(-1px)!important}
#nav-search .search-input,.search-form input[type='text'],.search-form input[name='q']{background:#111!important;color:#fff!important;border:1px solid #333!important;border-radius:8px!important}
#nav-search .search-input:focus,.search-form input[name='q']:focus{border-color:#777!important;outline:2px solid #ffffff18!important}
.item-post .post-body{overflow-wrap:anywhere}
.item-post .post-body a.button,.item-post .post-body .button,.item-post .post-body .btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;margin:5px 4px;padding:11px 16px;background:#171717;color:#fff!important;border:1px solid #454545;border-radius:8px!important;text-decoration:none;transition:background .2s ease,border-color .2s ease,transform .2s ease}
