#cinhubCinemaLoader .cinhub-loader-track{height:7px;width:min(68vw,260px);margin:0 auto 12px;border:1px solid #9f8014;border-radius:30px;background:#171508;overflow:hidden;box-shadow:0 0 9px rgba(255,213,42,.2)}
#cinhubCinemaLoader .cinhub-loader-progress{height:100%;width:0;border-radius:30px;background:linear-gradient(90deg,#a77c00,#ffd52a,#fff1a3);box-shadow:0 0 10px #ffd52a;animation:cinhubLoaderFill 3s linear forwards}
#cinhubCinemaLoader .cinhub-loader-label{font:600 12px Arial,Helvetica,sans-serif;letter-spacing:.5px;color:#ffd52a;text-shadow:0 0 7px rgba(255,213,42,.38);text-align:center}
@keyframes cinhubLoaderFill{from{width:0}to{width:100%}}
@media(max-width:380px){#cinhubCinemaLoader .cinhub-loader-inner{padding:12px}#cinhubCinemaLoader .cinhub-loader-logo{width:112px;height:112px;margin-bottom:12px}#cinhubCinemaLoader .cinhub-loader-title{font-size:25px}#cinhubCinemaLoader .cinhub-loader-desc{font-size:12px;margin-bottom:16px}}
@media(prefers-reduced-motion:reduce){#cinhubCinemaLoader .cinhub-loader-progress{animation-duration:3s}}



/* CINHUB4U CINEMA REFRESH — modern typography, cinematic charcoal and crimson */
:root{--main-font:'Inter','Poppins',system-ui,sans-serif;--sub-font:'Inter','Poppins',system-ui,sans-serif;--title-color:#f4f4f7;--cinema-accent:#ff3155;--cinema-bg:#090a0f;--cinema-panel:#14151d;--cinema-muted:#a9aab6}
html{scroll-behavior:smooth;scroll-padding-top:84px}
body{background-color:var(--cinema-bg);color:#f4f4f7;font-family:var(--sub-font);font-size:14px;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
a{transition:color .22s ease,background-color .22s ease,border-color .22s ease}
a:hover{color:var(--cinema-accent)}
#header-wrapper,#header,#main-menu,.mobile-menu{background:#0b0c12}
#main-menu ul>li>a{font-family:var(--main-font);font-size:14px;font-weight:700;letter-spacing:.15px;transition:color .2s ease,background .2s ease}
#main-menu ul>li:hover>a,#main-menu ul>li>a:hover{color:var(--cinema-accent)}
.title-wrap,.sidebar .widget-title{height:auto;min-height:42px;line-height:1.35;background:linear-gradient(100deg,#191a24,#101117);border:0;border-left:4px solid var(--cinema-accent);border-radius:5px;padding:11px 14px;box-sizing:border-box;color:#fff;box-shadow:0 5px 18px rgba(0,0,0,.16)}
.title-wrap:after,.sidebar .widget-title:after{background:var(--cinema-accent)}
.featured-posts .feat-item,.index-post,.PopularPosts .post{transition:transform .25s ease,filter .25s ease}
.featured-posts .feat-item:hover,.index-post:hover,.PopularPosts .post:hover{transform:translateY(-4px)}
.featured-posts .feat-item .post-image-wrap,.featured-posts .feat-item .post-image-link,.index-post .post-image-wrap,.index-post .post-image-link,.PopularPosts .post-image-link{border-radius:9px;overflow:hidden;background:#171821;box-shadow:0 7px 22px rgba(0,0,0,.24)}
.featured-posts .feat-item img,.index-post img,.PopularPosts .post img{transition:transform .45s ease,filter .35s ease}
.featured-posts .feat-item:hover img,.index-post:hover img,.PopularPosts .post:hover img{transform:scale(1.045);filter:saturate(1.08)}
.featured-posts .post-title,.index-post .post-title,.PopularPosts .post-title{font-family:var(--main-font);font-weight:600;letter-spacing:-.15px;line-height:1.45}
.featured-posts .post-title a,.index-post .post-title a,.PopularPosts .post-title a{color:#f3f3f6}
.featured-posts .post-title a:hover,.index-post .post-title a:hover,.PopularPosts .post-title a:hover{color:var(--cinema-accent)}
.index-post .post-info,.featured-posts .post-info{background:transparent}
.label-info a,.cloud-label li a,.post-labels a{background:#20212b;color:#e9e9ef;border:1px solid #30313d;border-radius:20px;padding:4px 10px;transition:all .2s ease}
.label-info a:hover,.cloud-label li a:hover,.post-labels a:hover{background:var(--cinema-accent);border-color:var(--cinema-accent);color:#fff}
button,.button,.post-body a.button,.post-body .download-button{border-radius:7px;transition:transform .2s ease,box-shadow .2s ease,background .2s ease}
button:hover,.button:hover,.post-body a.button:hover,.post-body .download-button:hover{transform:translateY(-1px);box-shadow:0 5px 18px rgba(255,49,85,.2)}
#cinhubCinemaLoader{background:radial-gradient(ellipse at 50% 42%,#30101c 0%,#130a11 38%,#08090e 76%,#050609 100%)}
#cinhubCinemaLoader .cinhub-loader-logo{border-color:#ff3155;background:radial-gradient(circle,#24101a 0%,#08090e 74%);box-shadow:0 0 0 4px rgba(255,49,85,.1),0 0 26px rgba(255,49,85,.38),inset 0 0 12px rgba(255,49,85,.12)}
#cinhubCinemaLoader .cinhub-loader-title{font-family:'Childer','Poppins',sans-serif;color:#fff;text-shadow:0 0 18px rgba(255,49,85,.45);letter-spacing:2px}
#cinhubCinemaLoader .cinhub-loader-desc{font-family:'Childer','Poppins',sans-serif;color:#d8d8e0;letter-spacing:.3px}
#cinhubCinemaLoader .cinhub-loader-track{border-color:#70263a;background:#1a1017;box-shadow:0 0 12px rgba(255,49,85,.16)}
#cinhubCinemaLoader .cinhub-loader-progress{background:linear-gradient(90deg,#b81439,#ff3155,#ff9bb0);box-shadow:0 0 10px rgba(255,49,85,.8)}
#cinhubCinemaLoader .cinhub-loader-label{color:#ff7892;text-shadow:0 0 7px rgba(255,49,85,.3);font-family:'Childer','Poppins',sans-serif}
:focus-visible{outline:2px solid #ff6682;outline-offset:3px}
@media(max-width:600px){.title-wrap,.sidebar .widget-title{padding:10px 12px}.featured-posts .feat-item:hover,.index-post:hover,.PopularPosts .post:hover{transform:none}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.featured-posts .feat-item,.index-post,.PopularPosts .post,.featured-posts .feat-item img,.index-post img,.PopularPosts .post img{transition:none!important}}


/* CINHUB4U PREMIUM STREAMING CARDS */
:root{--cinema-card:#11131b;--cinema-line:rgba(255,255,255,.075);--cinema-accent:#ff3155}
/* Clean, consistent poster frames */
.featured-posts .feat-item .post-image-wrap,.featured-posts .feat-item .post-image-link,.index-post .post-image-wrap,.index-post .post-image-link,.PopularPosts .post-image-link{position:relative;display:block;border:1px solid var(--cinema-line);border-radius:12px;overflow:hidden;background:#11131b;box-shadow:0 8px 24px rgba(0,0,0,.28);isolation:isolate}
.featured-posts .feat-item img,.index-post img,.PopularPosts .post img{display:block;width:100%;height:auto;object-fit:cover;transition:transform .45s cubic-bezier(.2,.7,.2,1),filter .35s ease}
/* Richer image treatment without obscuring poster artwork */
.featured-posts .feat-item:hover img,.index-post:hover img,.PopularPosts .post:hover img{transform:scale(1.055);filter:brightness(1.04) saturate(1.12)}
.featured-posts .feat-item,.index-post,.PopularPosts .post{min-width:0;border-radius:13px;transition:transform .25s ease,box-shadow .25s ease}
.featured-posts .feat-item:hover,.index-post:hover,.PopularPosts .post:hover{box-shadow:0 12px 28px rgba(0,0,0,.22)}
.featured-posts .post-title,.index-post .post-title,.PopularPosts .post-title{font-family:'Inter','Poppins',system-ui,sans-serif;font-size:clamp(12px,1.15vw,15px);font-weight:700;line-height:1.42;letter-spacing:-.25px;margin-top:9px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:2.84em}
.featured-posts .post-title a,.index-post .post-title a,.PopularPosts .post-title a{color:#f5f5f8;text-decoration:none;transition:color .2s ease}
.featured-posts .post-title a:hover,.index-post .post-title a:hover,.PopularPosts .post-title a:hover{color:#ff718a}
.featured-posts .post-info,.index-post .post-info,.PopularPosts .post-info{color:#9b9daa;font-size:11px;line-height:1.5}
.featured-posts .post-info a,.index-post .post-info a{color:#c1c2cc}
/* Give section headings a streaming-catalog feel */
.title-wrap,.sidebar .widget-title{box-shadow:inset 0 1px rgba(255,255,255,.025),0 5px 18px rgba(0,0,0,.12)}
/* Tap-friendly cards on phones; avoid hover lift on touch screens */
@media(max-width:600px){.featured-posts .feat-item,.index-post,.PopularPosts .post{border-radius:10px}.featured-posts .feat-item .post-image-wrap,.featured-posts .feat-item .post-image-link,.index-post .post-image-wrap,.index-post .post-image-link,.PopularPosts .post-image-link{border-radius:10px}.featured-posts .post-title,.index-post .post-title,.PopularPosts .post-title{font-size:12px;line-height:1.4;margin-top:7px;min-height:2.8em}.featured-posts .feat-item:hover,.index-post:hover,.PopularPosts .post:hover{transform:none;box-shadow:none}}
@media(prefers-reduced-motion:reduce){.featured-posts .feat-item img,.index-post img,.PopularPosts .post img{transition:none!important}}


/* Childer font supplied by site owner; embedded for reliable use across the whole theme */
@font-face{font-family:'Childer';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/otf;base64,) format('opentype')}

/* Childer typography across site text; icon fonts are intentionally excluded */
body,button,input,select,textarea,h1,h2,h3,h4,h5,h6,.post-title,.entry-title,.item-title,.post-body,.post-snippet,.blog-posts,.widget-title,#main-menu a,.label-name,.cinhub-loader-title,.cinhub-loader-desc,.cinhub-loader-label{font-family:'Childer','Poppins','Noto Serif Khmer',sans-serif}

/* FINAL OVERRIDE: use the uploaded Childer font consistently across all visible theme text */
body, body :not(i):not(.fa):not([class^='fa-']):not([class*=' fa-']):not(svg),
body button, body input, body select, body textarea,
body .featured-posts .post-title, body .featured-posts .post-title a,
body .index-post .post-title, body .index-post .post-title a,
body .PopularPosts .post-title, body .PopularPosts .post-title a,
body .cinhub-telegram-join, body .cinhub-badge, body .movie-quality,
#cinhubCinemaLoader, #cinhubCinemaLoader *:not(i):not(.fa):not([class^='fa-']):not([class*=' fa-']){font-family:'Childer',sans-serif!important}
/* Keep movie descriptions comfortable to read on small screens */
.featured-posts .post-title,.index-post .post-title,.PopularPosts .post-title{font-size:clamp(13px,1.2vw,16px);line-height:1.5;letter-spacing:0;overflow-wrap:anywhere}
@media(max-width:600px){.featured-posts .post-title,.index-post .post-title,.PopularPosts .post-title{font-size:13px;line-height:1.48;letter-spacing:0}}

/* Childer FONT FIX: explicitly target the actual Blogger homepage/index movie-title markup */
.index .blog-posts .post h3.post-title,
.index .blog-posts .post h3.post-title a,
.index .blog-posts .post h2.post-title,
.index .blog-posts .post h2.post-title a,
.blog-posts .post h3.post-title,
.blog-posts .post h3.post-title a,
.blog-posts .post h2.post-title,
.blog-posts .post h2.post-title a,
.post-outer .post-title,
.post-outer .post-title a,
.post-title, .post-title a, .entry-title, .entry-title a,
.index-post .post-title, .index-post .post-title a,
.featured-posts .post-title, .featured-posts .post-title a,
.PopularPosts .post-title, .PopularPosts .post-title a,
.cinhub-latest-track .post-title, #cinhub-latest-track .post-title,
.cinhub-home-description h2, .widget-title {
  font-family: 'Childer', sans-serif !important;
  font-weight: 400 !important;
  font-style: normal !important;
}
/* Preserve legibility and avoid clipping the decorative title font on phones */
.blog-posts .post h3.post-title, .blog-posts .post h3.post-title a,
.blog-posts .post h2.post-title, .blog-posts .post h2.post-title a,
.index-post .post-title, .index-post .post-title a {
  line-height: 1.45 !important;
  letter-spacing: 0 !important;
  overflow-wrap: anywhere;
}

/* FINAL CINHUB4U FIX: use uploaded Childer font on movie-card titles only */
.index-post .post-title,
.index-post .post-title a,
.index-post .post-info .post-title,
.index-post .post-info .post-title a,
.index-post h2.post-title,
.index-post h2.post-title a,
.blog-posts .post-title,
.blog-posts .post-title a,
.post-outer .post-title,
.post-outer .post-title a,
#main .index-post .post-title,
#main .index-post .post-title a {
  font-family: 'Childer', sans-serif !important;
  font-style: normal !important;
  font-weight: 400 !important;
  letter-spacing: .15px !important;
  text-transform: none !important;
}
/* Keep title text legible and prevent cramped wrapping on phones */
.index-post .post-title a,
.index-post .post-info .post-title a,
.blog-posts .post-title a,
.post-outer .post-title a {
  line-height: 1.45 !important;
  overflow-wrap: anywhere;
}



/* CINHUB4U PREMIUM GLASS MOVIE CARDS */
.index-post-inside-wrap,
.featured-item-inner,
#top-popular-slider .post,
#cinhub-latest-track .post,
.PopularPosts .widget-content li {
  background: linear-gradient(145deg, rgba(255,255,255,.105), rgba(255,255,255,.025)) !important;
  background-color: rgba(18,18,22,.68) !important;
  border: 1px solid rgba(255,255,255,.16) !important;
  border-radius: 16px !important;
  box-shadow: 0 10px 28px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.08) !important;
  -webkit-backdrop-filter: blur(12px) saturate(135%);
  backdrop-filter: blur(12px) saturate(135%);
  overflow: hidden;
  animation: none !important;
  transition: transform .25s ease, border-color .25s ease, box-shadow .25s ease !important;
}
.index-post-inside-wrap:hover,
.featured-item-inner:hover,
#top-popular-slider .post:hover,
#cinhub-latest-track .post:hover {
  transform: translateY(-4px);
  border-color: rgba(255,73,59,.72) !important;
  box-shadow: 0 16px 36px rgba(0,0,0,.48), 0 0 18px rgba(255,73,59,.13), inset 0 1px 0 rgba(255,255,255,.12) !important;
}
.index-post .post-info,
.index-post .post-info-inner,
.featured-item-inner .post-info,
#top-popular-slider .post-info {
  background: linear-gradient(180deg, rgba(20,20,24,.60), rgba(8,8,10,.92)) !important;
}
.index-post .post-title a,
.featured-posts .post-title a,
#top-popular-slider .post-title a,
#cinhub-latest-track .post-title a {
  color: #fff !important;
  text-shadow: 0 1px 10px rgba(0,0,0,.55);
}
.index-post .post-image-wrap img,
.index-post .post-image img,
.featured-item-inner img,
#top-popular-slider img,
#cinhub-latest-track img {
  transition: transform .35s ease, filter .35s ease;
}
.index-post-inside-wrap:hover img,
.featured-item-inner:hover img { transform: scale(1.035); filter: saturate(1.08); }
@media (max-width: 767px) {
  .index-post-inside-wrap,.featured-item-inner,#top-popular-slider .post,#cinhub-latest-track .post {
    border-radius: 13px !important;
    -webkit-backdrop-filter: blur(8px) saturate(125%);
    backdrop-filter: blur(8px) saturate(125%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .index-post-inside-wrap,.featured-item-inner,#top-popular-slider .post,#cinhub-latest-track .post,
  .index-post .post-image-wrap img,.index-post .post-image img,.featured-item-inner img { transition:none !important; }
}


/* Cinhub4u post home button and reactions */
.cinhub-home-post-wrap{display:block;margin:12px 0 16px;width:100%;} .cinhub-home-post-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;width:auto;max-width:100%;box-sizing:border-box;padding:9px 16px;border:1px solid rgba(255,82,82,.58);border-radius:11px;background:linear-gradient(135deg,rgba(229,57,53,.34),rgba(150,20,28,.20));color:#fff!important;font-weight:750;font-size:13px;letter-spacing:.15px;text-decoration:none!important;box-shadow:0 5px 16px rgba(229,57,53,.18),inset 0 1px 0 rgba(255,255,255,.12);backdrop-filter:blur(12px) saturate(140%);-webkit-backdrop-filter:blur(12px) saturate(140%);transition:transform .2s,background .2s,border-color .2s,box-shadow .2s;} .cinhub-home-post-btn:hover{transform:translateY(-1px);background:linear-gradient(135deg,rgba(255,70,70,.46),rgba(170,24,32,.28));border-color:rgba(255,105,105,.78);box-shadow:0 7px 20px rgba(229,57,53,.25),inset 0 1px 0 rgba(255,255,255,.16);}
.cinhub-reactions{clear:both;margin:28px 0 22px;padding:18px;border:1px solid rgba(255,255,255,.14);border-radius:18px;background:linear-gradient(135deg,rgba(255,255,255,.09),rgba(255,255,255,.035));box-shadow:0 10px 28px rgba(0,0,0,.16);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);}
.cinhub-reactions-title{font-size:19px;font-weight:800;margin:0 0 6px;color:inherit;text-align:center;}
.cinhub-reactions-subtitle{font-size:12px;opacity:.72;text-align:center;margin:0 0 16px;}
.cinhub-reaction-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;}
.cinhub-reaction-btn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;min-width:0;padding:12px 5px;border:1px solid rgba(255,255,255,.15);border-radius:13px;background:rgba(255,255,255,.055);color:inherit;font:inherit;cursor:pointer;transition:transform .18s,border-color .18s,background .18s;}
.cinhub-reaction-btn:hover{transform:translateY(-2px);background:rgba(255,255,255,.11);}
.cinhub-reaction-btn.is-selected{border-color:#e53935;background:rgba(229,57,53,.17);box-shadow:0 0 0 1px rgba(229,57,53,.2) inset;}
.cinhub-reaction-emoji{font-size:25px;line-height:1.1}.cinhub-reaction-name{font-size:12px;font-weight:700}.cinhub-reaction-count{font-size:12px;opacity:.78;font-variant-numeric:tabular-nums}
@media(max-width:480px){.cinhub-reactions{padding:13px}.cinhub-reaction-list{gap:6px}.cinhub-reaction-btn{padding:10px 3px}.cinhub-reaction-name{font-size:11px}}

