(function(){
  var input=document.getElementById('cinhub-search-input');
  var box=document.getElementById('cinhub-search-suggestions');
  if(!input||!box)return;
  var timer=null,lastQuery='';
  function closeBox(){box.hidden=true;box.innerHTML='';}
  function showItems(items,q){
    box.innerHTML='';
    if(!items.length){var empty=document.createElement('div');empty.className='cinhub-suggest-empty';empty.textContent='No matching movie titles found. Press Search to see all results.';box.appendChild(empty);box.hidden=false;return;}
    items.slice(0,7).forEach(function(item){var a=document.createElement('a');a.href=item.url;a.setAttribute('role','option');a.textContent=item.title;box.appendChild(a);});
    box.hidden=false;
  }
  input.addEventListener('input',function(){
    var q=input.value.trim();clearTimeout(timer);
    if(q.length<2){closeBox();return;}
    timer=setTimeout(function(){
      if(q===lastQuery)return;lastQuery=q;
      var url='/feeds/posts/default?alt=json&max-results=12';
      fetch(url).then(function(r){if(!r.ok)throw new Error('feed');return r.json();}).then(function(data){
        var entries=data&&data.feed&&data.feed.entry?data.feed.entry:[];
        var query=q.toLowerCase(),matches=[];
        entries.forEach(function(entry){
          var title=entry.title&&entry.title.$t?entry.title.$t:'';
          if(title.toLowerCase().indexOf(query)!==-1){var links=entry.link||[],href='';for(var i=0;i<links.length;i++){if(links[i].rel==='alternate'){href=links[i].href;break;}}if(href)matches.push({title:title,url:href});}
        });
        if(input.value.trim()===q)showItems(matches,q);
      }).catch(function(){closeBox();});
    },220);
  });
  document.addEventListener('click',function(e){if(!e.target.closest||!e.target.closest('#cinhub-search-wrap'))closeBox();});
  input.addEventListener('keydown',function(e){if(e.key==='Escape')closeBox();});
})();
