//
    (function(){
      var track=document.getElementById('cinhub-latest-track');
      if(!track) return;
      function getLink(entry){
        var links=entry.link||[];
        for(var i=0;i<links.length;i++){if(links[i].rel==='alternate') return links[i].href;}
        return '#';
      }
      function getImage(entry){
        if(entry.media$thumbnail && entry.media$thumbnail.url) return entry.media$thumbnail.url.replace(/\/s72-c\//,'/s640/');
        var html=(entry.content&&entry.content.$t)||(entry.summary&&entry.summary.$t)||'';
        var match=html.match(/<img[^>]+src=["']([^"']+)["']/i);
        return match?match[1]:'';
      }
      function initSlider(){
        var cards=Array.prototype.slice.call(track.querySelectorAll('.post'));
        if(!cards.length) return;
        var current=0, timer=null;
        var controls=document.createElement('div'); controls.className='cinhub-slider-controls';
        var prev=document.createElement('button'); prev.type='button'; prev.className='cinhub-slider-arrow cinhub-slider-prev'; prev.setAttribute('aria-label','Previous movie'); prev.textContent='‹';
        var next=document.createElement('button'); next.type='button'; next.className='cinhub-slider-arrow cinhub-slider-next'; next.setAttribute('aria-label','Next movie'); next.textContent='›';
        var dots=document.createElement('div'); dots.className='cinhub-slider-dots'; dots.setAttribute('aria-label','Choose featured movie');
        var dotButtons=[];
        cards.forEach(function(card,i){var dot=document.createElement('button');dot.type='button';dot.className='cinhub-slider-dot';dot.setAttribute('aria-label','Show movie '+(i+1));dot.addEventListener('click',function(){show(i);restart();});dots.appendChild(dot);dotButtons.push(dot);});
        function show(index){
          current=(index+cards.length)%cards.length;
          cards.forEach(function(card,i){
            card.classList.remove('cinhub-active','cinhub-next','cinhub-prev','cinhub-hidden');
            if(i===current) card.classList.add('cinhub-active');
            else if(i===(current+1)%cards.length) card.classList.add('cinhub-next');
            else if(i===(current-1+cards.length)%cards.length) card.classList.add('cinhub-prev');
            else card.classList.add('cinhub-hidden');
          });
          dotButtons.forEach(function(dot,i){dot.classList.toggle('is-active',i===current);dot.setAttribute('aria-current',i===current?'true':'false');});
        }
        function advance(){show(current+1);}
        function start(){if(!timer && cards.length>1 && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) timer=window.setInterval(advance,4500);}
        function stop(){if(timer){window.clearInterval(timer);timer=null;}}
        function restart(){stop();start();}
        prev.addEventListener('click',function(){show(current-1);restart();});
        next.addEventListener('click',function(){show(current+1);restart();});
        controls.appendChild(prev);controls.appendChild(next);track.appendChild(controls);track.appendChild(dots);
        show(0);
        track.addEventListener('mouseenter',stop); track.addEventListener('mouseleave',start);
        track.addEventListener('focusin',stop); track.addEventListener('focusout',start);
        track.addEventListener('touchstart',stop,{passive:true}); track.addEventListener('touchend',function(){window.setTimeout(start,1200);},{passive:true});
        start();
      }
      fetch('/feeds/posts/default?alt=json&max-results=12')
        .then(function(response){if(!response.ok) throw new Error('Feed unavailable'); return response.json();})
        .then(function(data){
          var entries=(data.feed&&data.feed.entry)||[];
          track.textContent='';
          if(!entries.length){track.textContent='No posts found yet.';return;}
          entries.forEach(function(entry){
            var card=document.createElement('article'); card.className='post';
            var content=document.createElement('div'); content.className='post-content';
            var link=document.createElement('a'); link.className='post-image-link'; link.href=getLink(entry); link.setAttribute('aria-label',entry.title?entry.title.$t:'Open post');
            var image=getImage(entry);
            if(image){var img=document.createElement('img'); img.className='post-thumb'; img.src=image; img.alt=entry.title?entry.title.$t:''; img.loading='lazy'; link.appendChild(img);}
            else {var placeholder=document.createElement('span'); placeholder.className='cinhub-no-thumb'; placeholder.textContent='Cinhub4u'; link.appendChild(placeholder);}
            var info=document.createElement('div'); info.className='post-info';
            var title=document.createElement('h3'); title.className='post-title';
            var titleLink=document.createElement('a'); titleLink.href=getLink(entry); titleLink.textContent=(entry.title&&entry.title.$t)||'Untitled post'; title.appendChild(titleLink);
            info.appendChild(title); content.appendChild(link); content.appendChild(info); card.appendChild(content); track.appendChild(card);
          });
          initSlider();
        })
        .catch(function(){track.textContent='Unable to load posts. Check that the Blogger posts feed is enabled.';});
    })();
    //

