(function(){
 function initCinhubCategoryDrawer(){
   var holder=document.querySelector('.mobile-menu');
   if(!holder) return;
   var source=document.querySelector('.tags-wrapper .menu-cat ul');
   if(source){
     var list=source.cloneNode(true);
     list.removeAttribute('id');
     list.querySelectorAll('[id]').forEach(function(el){el.removeAttribute('id')});
     holder.innerHTML='';
     holder.appendChild(list);
   }else if(!holder.querySelector('ul')){
     var main=document.querySelector('#main-menu-nav');
     if(main) holder.appendChild(main.cloneNode(true));
   }
   var toggle=document.querySelector('.mobile-menu-toggle');
   var outer=document.getElementById('outer-wrapper');
   if(toggle && outer && !toggle.getAttribute('data-cinhub-bound')){
     toggle.setAttribute('data-cinhub-bound','1');
     toggle.setAttribute('role','button');
     toggle.setAttribute('tabindex','0');
     toggle.setAttribute('aria-label','Open categories menu');
     function flip(){
       var opened=outer.classList.toggle('nav-active');
       toggle.setAttribute('aria-expanded',opened?'true':'false');
       toggle.setAttribute('aria-label',opened?'Close categories menu':'Open categories menu');
     }
     toggle.addEventListener('click',function(e){e.preventDefault();flip()});
     toggle.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();flip()}});
     document.addEventListener('click',function(e){if(!outer.contains(e.target)&&outer.classList.contains('nav-active'))outer.classList.remove('nav-active')});
   }
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initCinhubCategoryDrawer);else initCinhubCategoryDrawer();
})();
