//
(function(){
  function startCinhubSliders(){
    var sliders=document.querySelectorAll('#feat-section .featured-posts');
    Array.prototype.forEach.call(sliders,function(slider){
      if(slider.getAttribute('data-cinhub-slider')) return;
      slider.setAttribute('data-cinhub-slider','1');
      slider.style.overflowX='auto';
      slider.style.scrollBehavior='smooth';
      slider.style.scrollbarWidth='none';
      window.setInterval(function(){
        var first=slider.querySelector('.feat-item');
        if(!first) return;
        var step=first.getBoundingClientRect().width;
        if(slider.scrollLeft+slider.clientWidth>=slider.scrollWidth-8){
          slider.scrollTo({left:0,behavior:'smooth'});
        }else{
          slider.scrollBy({left:step,behavior:'smooth'});
        }
      },3000);
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',startCinhubSliders);
  else startCinhubSliders();
})();
