//
(function(){
  function initCinhubJoinNotice(){
    var backdrop=document.getElementById('cinhubJoinNoticeBackdrop');
    var dismiss=document.getElementById('cinhubJoinNoticeDismiss');
    if(!backdrop||!dismiss) return;
    var repeatTimer=null;
    var storageKey='cinhubTelegramNoticeNextAt';
    var cooldown=86400000; // 24 hours: show the Telegram notice at most once per day after dismissal
    function getNextAt(){
      try{return parseInt(window.localStorage.getItem(storageKey)||'0',10)||0;}catch(err){return 0;}
    }
    function setNextAt(value){
      try{window.localStorage.setItem(storageKey,String(value));}catch(err){}
    }
    function showNotice(){
      // Record the display time immediately, so navigating to another page
      // cannot reopen the notice before the 24-hour cooldown expires.
      setNextAt(Date.now()+cooldown);
      backdrop.style.display='flex';
      document.body.classList.add('cinhub-join-notice-open');
    }
    function closeNotice(){
      backdrop.style.display='none';
      document.body.classList.remove('cinhub-join-notice-open');
      setNextAt(Date.now()+cooldown);
      if(repeatTimer) window.clearTimeout(repeatTimer);
      repeatTimer=window.setTimeout(showNotice,cooldown);
    }
    // Store the cooldown across page changes so navigation does not reopen the popup.
    var remaining=getNextAt()-Date.now();
    if(remaining<=0){showNotice();}
    else {repeatTimer=window.setTimeout(showNotice,remaining);}
    dismiss.addEventListener('click',closeNotice);
    document.addEventListener('keydown',function(e){if(e.key==='Escape'&&backdrop.style.display!=='none')closeNotice();});
    backdrop.addEventListener('click',function(e){if(e.target===backdrop)closeNotice();});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initCinhubJoinNotice);else initCinhubJoinNotice();
})();
//

//
(function(){
  function setNetworkState(){
    var offline=(navigator.onLine===false);
    document.body.classList.toggle('cinhub-network-offline',offline);
    document.documentElement.classList.toggle('cinhub-network-offline',offline);
  }
  window.addEventListener('online',setNetworkState);
  window.addEventListener('offline',setNetworkState);
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',setNetworkState);
  else setNetworkState();
})();
//

// Cinhub4u reactions: browser-local counts. Shared visitor totals require a shared backend.
//
(function(){
  var panels=document.querySelectorAll('.cinhub-reactions');
  if(!panels.length) return;
  var reactions=['ultimate','super','thanks','sad','angry','favourite'];
  function read(key){try{return JSON.parse(localStorage.getItem(key)||'{}')}catch(e){return {}}}
  function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){return false}}
  panels.forEach(function(panel){
    var url=panel.getAttribute('data-post-url')||location.pathname;
    var storageKey='cinhub4uReactions:'+url;
    var voteKey='cinhub4uReactionVote:'+url;
    var counts=read(storageKey);var vote=localStorage.getItem(voteKey)||'';
    function render(){
      reactions.forEach(function(name){var node=panel.querySelector('[data-count="'+name+'"]');if(node)node.textContent=Number(counts[name]||0).toLocaleString();});
      panel.querySelectorAll('.cinhub-reaction-btn').forEach(function(btn){var selected=btn.getAttribute('data-reaction')===vote;btn.classList.toggle('is-selected',selected);btn.setAttribute('aria-pressed',selected?'true':'false');});
    }
    panel.querySelectorAll('.cinhub-reaction-btn').forEach(function(btn){btn.addEventListener('click',function(){
      var next=btn.getAttribute('data-reaction');if(!next)return;
      if(vote===next){counts[next]=Math.max(0,Number(counts[next]||0)-1);vote='';localStorage.removeItem(voteKey);}
      else{if(vote)counts[vote]=Math.max(0,Number(counts[vote]||0)-1);counts[next]=Number(counts[next]||0)+1;vote=next;localStorage.setItem(voteKey,vote);}
      if(!write(storageKey,counts)){return;}render();
    });});render();
  });
})();
//
